$ErrorActionPreference = 'Stop'
$packages = @(
  [pscustomobject]@{ Arch = 'x64'; Path = 'dist-desktop/win-unpacked' },
  [pscustomobject]@{ Arch = 'arm64'; Path = 'dist-desktop/win-arm64-unpacked' }
)
foreach ($package in $packages) {
  if (-not (Test-Path -LiteralPath $package.Path -PathType Container)) {
    throw "Signed release produced no $($package.Arch) outer package at $($package.Path)."
  }

  $appExecutable = Join-Path $package.Path "$env:OK_DESKTOP_PRODUCT_NAME.exe"
  if (-not (Test-Path -LiteralPath $appExecutable -PathType Leaf)) {
    throw "Signed $($package.Arch) release package has no $env:OK_DESKTOP_PRODUCT_NAME.exe."
  }
  $signature = Get-AuthenticodeSignature $appExecutable
  if ($signature.Status -ne 'Valid') {
    throw "Our signing pass did not leave a valid signature on ${appExecutable}: $($signature.Status)"
  }
}
"### Windows signing attestation: PASSED`n`nBoth outer architectures carry a validly signed app." |
  Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY

$ErrorActionPreference = 'Stop'
foreach ($packagePath in @('dist-desktop/win-unpacked', 'dist-desktop/win-arm64-unpacked')) {
  $pairDirectories = @(Get-ChildItem $packagePath -Recurse -Directory -Filter 'conpty' |
    Where-Object { $_.FullName -match 'node-pty[\\/]prebuilds[\\/]win32-(x64|arm64)[\\/]conpty$' })
  if ($pairDirectories.Count -ne 2) {
    throw "Expected both ConPTY architecture directories in the release package at ${packagePath}; found $($pairDirectories.Count)."
  }
  foreach ($directory in $pairDirectories) {
    foreach ($name in @('conpty.dll', 'OpenConsole.exe')) {
      $path = Join-Path $directory.FullName $name
      if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Packaged Microsoft ConPTY pair is incomplete: $path"
      }
      $signature = Get-AuthenticodeSignature $path
      if ($signature.Status -ne 'Valid') {
        throw "Microsoft signature is not valid on ${path}: $($signature.Status)"
      }
      if ($signature.SignerCertificate.Subject -notmatch 'Microsoft') {
        throw "Expected the original Microsoft signer on ${path}; got $($signature.SignerCertificate.Subject)"
      }
    }
  }
}
"### Windows release signature rider: PASSED`n`nMicrosoft signatures remain valid on every packaged ConPTY pair." |
  Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY

$ErrorActionPreference = 'Stop'
if ($env:OK_SIGNING_REQUESTED -ne 'true') {
  throw 'Signature rider ran without a signing-enabled package step.'
}

$packages = @(
  [pscustomobject]@{ Arch = 'x64'; Path = 'dist-desktop/win-unpacked' },
  [pscustomobject]@{ Arch = 'arm64'; Path = 'dist-desktop/win-arm64-unpacked' }
)
foreach ($package in $packages) {
  if (-not (Test-Path -LiteralPath $package.Path -PathType Container)) {
    throw "Signing-enabled build produced no $($package.Arch) outer package at $($package.Path)."
  }

  $appExecutable = Join-Path $package.Path "$env:OK_DESKTOP_PRODUCT_NAME.exe"
  if (-not (Test-Path -LiteralPath $appExecutable -PathType Leaf)) {
    throw "Signing-enabled $($package.Arch) package has no $env:OK_DESKTOP_PRODUCT_NAME.exe."
  }
  $signature = Get-AuthenticodeSignature $appExecutable
  if ($signature.Status -ne 'Valid') {
    throw "Our signing pass did not leave a valid signature on ${appExecutable}: $($signature.Status)"
  }

  $pairDirectories = @(Get-ChildItem $package.Path -Recurse -Directory -Filter 'conpty' |
    Where-Object { $_.FullName -match 'node-pty[\\/]prebuilds[\\/]win32-(x64|arm64)[\\/]conpty$' })
  if ($pairDirectories.Count -ne 2) {
    throw "Expected both ConPTY architecture directories in the $($package.Arch) package; found $($pairDirectories.Count)."
  }
  foreach ($directory in $pairDirectories) {
    foreach ($name in @('conpty.dll', 'OpenConsole.exe')) {
      $path = Join-Path $directory.FullName $name
      if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw "Packaged Microsoft ConPTY pair is incomplete: $path"
      }
      $signature = Get-AuthenticodeSignature $path
      if ($signature.Status -ne 'Valid') {
        throw "Microsoft signature is not valid on ${path}: $($signature.Status)"
      }
      if ($signature.SignerCertificate.Subject -notmatch 'Microsoft') {
        throw "Expected the original Microsoft signer on ${path}; got $($signature.SignerCertificate.Subject)"
      }
    }
  }
}
Add-Content -LiteralPath $env:GITHUB_OUTPUT -Value 'signing_ran=true'
"### Windows signature rider: PASSED`n`nBoth outer architectures carry a signed app, and Microsoft signatures remain valid on every packaged ConPTY pair." |
  Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY

if ($env:OK_SIGNING_RAN -ne 'true') {
  throw 'Azure signing was requested, but both signed outer packages were not attested.'
}

